 import { gsap } from 'gsap';
import {
  Group,
  Mesh,
  BoxGeometry,
  CircleGeometry,
  PlaneGeometry,
  MeshStandardNodeMaterial,
  MeshPhysicalNodeMaterial,
  MeshBasicNodeMaterial,
  PointLight,
  SRGBColorSpace,
  NoColorSpace,
  RepeatWrapping
} from 'three/webgpu';
import { uv, texture, float } from 'three/tsl';

export default function createNode(config, ctx) {
  const colors = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  const root = new Group();

  const hoverGroup = new Group();
  root.add(hoverGroup);

  const liftGroup = new Group();
  hoverGroup.add(liftGroup);

  const materials = [];
  const geometries = [];
  const tweens = [];
  const primitiveResults = [];

  const panelWidth = 1.84;
  const panelHeight = 1.18;
  const panelDepth = 0.08;

  const panelGeo = new BoxGeometry(panelWidth, panelHeight, panelDepth);
  geometries.push(panelGeo);

  const panelMat = new MeshPhysicalNodeMaterial({
    color: colors.surface,
    metalness: 0.55,
    roughness: 0.65,
    clearcoat: 0.15,
    anisotropy: 0.35,
    anisotropyRotation: Math.PI * 0.25
  });
  panelMat.anisotropy = 0.35;
  materials.push(panelMat);

  const panel = new Mesh(panelGeo, panelMat);
  panel.position.z = -0.06;
  liftGroup.add(panel);

  const cardWidth = 1.6;
  const cardHeight = 1.0;
  const cardGeo = new PlaneGeometry(cardWidth, cardHeight, 64, 64);
  geometries.push(cardGeo);

  const cardMat = new MeshStandardNodeMaterial({
    color: '#ffffff',
    roughness: 0.45,
    metalness: 0.25
  });
  materials.push(cardMat);

  const card = new Mesh(cardGeo, cardMat);
  card.position.z = 0.045;
  liftGroup.add(card);

  ctx.textureLoader.loadTexture(config.imageUrl).then((colorTex) => {
    colorTex.colorSpace = SRGBColorSpace;
    colorTex.needsUpdate = true;
    cardMat.map = colorTex;
    cardMat.needsUpdate = true;
  });

  ctx.textureLoader.loadTexture(config.depthMapUrl).then((depthTex) => {
    depthTex.colorSpace = NoColorSpace;
    depthTex.wrapS = RepeatWrapping;
    depthTex.wrapT = RepeatWrapping;
    depthTex.needsUpdate = true;
    cardMat.displacementNode = texture(depthTex, uv()).r.mul(float(0.18));
    cardMat.needsUpdate = true;
  });

  const frameThick = 0.04;
  const frameMat = new MeshPhysicalNodeMaterial({
    color: colors.accent,
    emissive: colors.accent,
    emissiveIntensity: 0.2,
    roughness: 0.35,
    metalness: 0.4,
    transparent: true
  });
  materials.push(frameMat);

  function makeBar(w, h, x, y) {
    const g = new BoxGeometry(w, h, frameThick);
    geometries.push(g);
    const m = new Mesh(g, frameMat);
    m.position.set(x, y, 0.05);
    return m;
  }

  const outerW = cardWidth + frameThick * 2;
  const outerH = cardHeight + frameThick * 2;
  liftGroup.add(makeBar(outerW, frameThick, 0, cardHeight / 2 + frameThick / 2));
  liftGroup.add(makeBar(outerW, frameThick, 0, -cardHeight / 2 - frameThick / 2));
  liftGroup.add(makeBar(frameThick, cardHeight, -cardWidth / 2 - frameThick / 2, 0));
  liftGroup.add(makeBar(frameThick, cardHeight, cardWidth / 2 + frameThick / 2, 0));

  const shadowGeo = new CircleGeometry(0.7, 32);
  geometries.push(shadowGeo);
  const shadowMat = new MeshBasicNodeMaterial({
    color: '#000000',
    transparent: true,
    opacity: 0.5,
    depthWrite: false
  });
  materials.push(shadowMat);
  const shadow = new Mesh(shadowGeo, shadowMat);
  shadow.scale.set(1.15, 0.75, 1);
  shadow.position.z = 0.01;
  hoverGroup.add(shadow);

  const rimLight = new PointLight(colors.accent, 0.9, 8, 2);
  rimLight.position.set(1.2, 1.1, 1.2);
  root.add(rimLight);

  const fillLight = new PointLight(colors.paper, 0.55, 8, 2);
  fillLight.position.set(-1.2, -0.8, 1.0);
  root.add(fillLight);

  const primitives = config.cinematicPrimitives ?? [];
  for (const p of primitives) {
    if (ctx.primitives[p.name]) {
      const result = ctx.primitives[p.name](root, p.params ?? {});
      primitiveResults.push(result);
    }
  }

  let focused = false;

  const handlers = {
    pointerover: () => {
      tweens.push(
        gsap.to(liftGroup.position, { y: 0.15, duration: 0.35, ease: 'power2.out', overwrite: true }),
        gsap.to(frameMat, { emissiveIntensity: 1.1, duration: 0.3 })
      );
    },
    pointerout: () => {
      const targetInt = focused ? 0.6 : 0.2;
      tweens.push(
        gsap.to(liftGroup.position, { y: 0, duration: 0.35, ease: 'power2.out', overwrite: true }),
        gsap.to(frameMat, { emissiveIntensity: targetInt, duration: 0.3 })
      );
    },
    pointerdown: () => {
      tweens.push(
        gsap.to(liftGroup.scale, { x: 0.97, y: 0.97, z: 0.97, duration: 0.12, ease: 'back.out(1.7)' })
      );
    },
    pointerup: () => {
      tweens.push(
        gsap.to(liftGroup.scale, { x: 1, y: 1, z: 1, duration: 0.15, ease: 'power2.out' })
      );
    },
    click: () => {
      ctx.emit('hub-features.select', { from: config.id, hub: 'hub-features' });
    },
    focus: () => {
      focused = true;
      tweens.push(gsap.to(frameMat, { emissiveIntensity: 0.8, duration: 0.25 }));
    },
    blur: () => {
      focused = false;
      tweens.push(gsap.to(frameMat, { emissiveIntensity: 0.2, duration: 0.25 }));
    }
  };

  root.userData.handlers = handlers;

  root.userData.cleanup = () => {
    tweens.forEach((t) => t?.kill());
    primitiveResults.forEach((p) => p?.cleanup?.());
    materials.forEach((m) => {
      if (m.map) m.map.dispose();
      if (m.emissiveMap) m.emissiveMap.dispose();
      m.dispose();
    });
    geometries.forEach((g) => g.dispose());
  };

  return root;
}
